pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with very little space left
    if bin_residual < 15 {
        score += (15 - bin_residual) as f64 * 10.0;
    }

    // Reward bins that can fit the next item immediately
    if fitting_bins_count > 0 {
        score -= 2.0 * ((fitting_bins_count == 1) as u32) as f64;
    }

    // Penalize opening new bins
    if open_bins_count < total_items / 10 {
        score += (total_items / 10 - open_bins_count) as f64 * 1.5;
    }

    // Reward bins with higher mean residual
    score -= (mean_residual - post_residual as f64 / bin_capacity as f64).abs() * 3.0;

    // Penalize large items being placed in bins that are close to capacity
    if item_size > 80 && bin_residual < 25 {
        score += (item_size - 80) as f64 * 3.5;
    }

    // Reward bins with lookahead items that fit well
    if next_item_size > 0 {
        let next_fit = post_residual >= next_item_size;
        score -= (next_fit as u32).saturating_mul(4.0) as f64;
    }

    score
}

